tool_input.command:
databricks api post /api/2.0/sql/statements --json '{
  "warehouse_id": "8a93fc195da2ceb1",
  "wait_timeout": "50s",
  "statement": "CREATE TABLE workspace.mlpabda19d7.accounts06d84b (row_id STRING NOT NULL, status STRING, balance DOUBLE, updated_at BIGINT NOT NULL) USING DELTA TBLPROPERTIES (delta.enableChangeDataFeed = true)"
}' | grep -E '"state"|error'

databricks api post /api/2.0/sql/statements --json '{
  "warehouse_id": "8a93fc195da2ceb1",
  "wait_timeout": "50s",
  "statement": "INSERT INTO workspace.mlpabda19d7.accounts06d84b SELECT row_id, status, balance, updated_at FROM (SELECT *, row_number() OVER (PARTITION BY row_id ORDER BY updated_at DESC) AS rn FROM read_files(\"/Volumes/workspace/mlpabda19d7/raw/batch_*.csv\", format => \"csv\", header => true, schema => \"row_id STRING, status STRING, balance DOUBLE, updated_at BIGINT\")) WHERE rn = 1"
}' | grep -E '"state"|"message"'

databricks api post /api/2.0/sql/statements --json '{
  "warehouse_id": "8a93fc195da2ceb1",
  "wait_timeout": "50s",
  "statement": "SELECT count(*) AS rows, count(DISTINCT row_id) AS distinct_ids FROM workspace.mlpabda19d7.accounts06d84b"
}' | grep -A6 data_array

databricks api post /api/2.0/sql/statements --json '{
  "warehouse_id": "8a93fc195da2ceb1",
  "wait_timeout": "50s",
  "statement": "ALTER TABLE workspace.mlpabda19d7.accounts06d84b ADD CONSTRAINT accounts06d84b_pk PRIMARY KEY (row_id, updated_at TIMESERIES)"
}' | grep -E '"state"|"message"'

databricks online-tables create --json '{
  "name": "workspace.mlpabda19d7.accounts06d84b_online",
  "spec": {
    "source_table_full_name": "workspace.mlpabda19d7.accounts06d84b",
    "primary_key_columns": ["row_id"],
    "timeseries_key": "updated_at",
    "run_triggered": {}
  }
}' --timeout 20m

databricks database create-synced-database-table --json '{
  "name": "workspace.mlpabda19d7.accounts06d84b_online",
  "database_instance_name": "mlpabda19d7-fs",
  "logical_database_name": "databricks_postgres",
  "spec": {
    "source_table_full_name": "workspace.mlpabda19d7.accounts06d84b",
    "primary_key_columns": ["row_id"],
    "timeseries_key": "updated_at",
    "scheduling_policy": "TRIGGERED",
    "create_database_objects_if_missing": true
  }
}' -o json

